    TimetableEntry = apps.get_model('academics', 'TimetableEntry')
    StudyMaterial = apps.get_model('academics', 'StudyMaterial')
    db = schema_editor.connection.alias

    def get_subject(name, department, semester):
        subject, _ = Subject.objects.using(db).get_or_create(
            name=name.strip(), department=department.strip(), semester=semester,
        )
        return subject

    # Timetable and materials carry their own department/semester fields.
